insert into public.vocab_senses (id, source_key, word, word_norm, pos, level, category_id, meaning, example, sort) values
  (1, 'A1|adverbs-and-pronouns|outside', 'Outside', 'outside', 'adv.', 'A1', 1, 'In an open area, not inside.', 'The children are playing outside.', 10),
  (2, 'A1|adverbs-and-pronouns|always', 'Always', 'always', 'adv.', 'A1', 1, 'At all times, no exceptions.', 'I always brush my teeth.', 2),
  (3, 'A1|adverbs-and-pronouns|never', 'Never', 'never', 'adv.', 'A1', 1, 'Not at any time.', 'I never eat spicy food.', 6),
  (4, 'A1|adverbs-and-pronouns|usually', 'Usually', 'usually', 'adv.', 'A1', 1, 'In most cases.', 'I usually wake up early.', 16),
  (5, 'A1|adverbs-and-pronouns|often', 'Often', 'often', 'adv.', 'A1', 1, 'Many times.', 'We often go to the park.', 9),
  (6, 'A1|adverbs-and-pronouns|sometimes', 'Sometimes', 'sometimes', 'adv.', 'A1', 1, 'Not always, but occasionally.', 'Sometimes it rains in the summer.', 12),
  (7, 'A1|adverbs-and-pronouns|now', 'Now', 'now', 'adv.', 'A1', 1, 'At this moment.', 'I am busy right now.', 7),
  (8, 'A1|adverbs-and-pronouns|soon', 'Soon', 'soon', 'adv.', 'A1', 1, 'In a short time.', 'The train will arrive soon.', 13),
  (9, 'A1|adverbs-and-pronouns|too', 'Too', 'too', 'adv.', 'A1', 1, 'Also, in addition.', 'I want to go too!', 15),
  (10, 'A1|adverbs-and-pronouns|here', 'Here', 'here', 'adv.', 'A1', 1, 'At this place.', 'Put the box here.', 4),
  (11, 'A1|adverbs-and-pronouns|there', 'There', 'there', 'adv.', 'A1', 1, 'At another place.', 'Look over there at the bird.', 14),
  (12, 'A1|adverbs-and-pronouns|again', 'Again', 'again', 'adv.', 'A1', 1, 'One more time.', 'Please say that again.', 1),
  (13, 'A1|adverbs-and-pronouns|of-course', 'Of course', 'of course', 'adv.', 'A1', 1, 'Certainly, without a doubt.', 'Of course I will help you.', 8),
  (14, 'A1|adverbs-and-pronouns|really', 'Really', 'really', 'adv.', 'A1', 1, 'Actually, truly.', 'It is really hot today.', 11),
  (15, 'A1|adverbs-and-pronouns|why', 'Why', 'why', 'adv.', 'A1', 1, 'Asking for a reason.', 'Why are you crying?', 21),
  (16, 'A1|adverbs-and-pronouns|where', 'Where', 'where', 'adv.', 'A1', 1, 'Asking for a place.', 'Where do you live?', 19),
  (17, 'A1|adverbs-and-pronouns|when', 'When', 'when', 'adv.', 'A1', 1, 'Asking for a time.', 'When is your birthday?', 18),
