  (1168, 'A2|exercise-and-matches|skating', 'skating', 'skating', 'n.', 'A2', 50, 'The sport or activity of moving around quickly on skates.', 'Let''s go skating at the park.', 1175),
  (1169, 'A2|exercise-and-matches|ice-skate', 'ice skate', 'ice skate', 'n.', 'A2', 50, 'A boot with a blade at the bottom used to move quickly on ice.', 'Put on your ice skates before you go on the rink.', 1158),
  (1170, 'A2|exercise-and-matches|ice-skating', 'ice skating', 'ice skating', 'n.', 'A2', 50, 'The sport or activity of moving on ice with ice skates.', 'Ice skating is a popular winter activity in Canada.', 1159),
  (1171, 'A2|exercise-and-matches|snowboard', 'snowboard', 'snowboard', 'n.', 'A2', 50, 'A type of board used to move down snowy hills.', 'He carried his snowboard up the mountain.', 1178),
  (1172, 'A2|exercise-and-matches|snowboarding', 'snowboarding', 'snowboarding', 'n.', 'A2', 50, 'A winter sport or activity standing on a board to glide over snow, typically on mountains.', 'Snowboarding is harder than skiing.', 1179),
  (1173, 'A2|exercise-and-matches|skateboard', 'skateboard', 'skateboard', 'n.', 'A2', 50, 'A small board with two sets of wheels we stand on to move around by pushing one foot.', 'The teenager did a trick on his skateboard.', 1173),
  (1174, 'A2|exercise-and-matches|skateboarding', 'skateboarding', 'skateboarding', 'n.', 'A2', 50, 'The sport or activity of riding a skateboard.', 'He injured his knee while skateboarding.', 1174),
  (1175, 'A2|exercise-and-matches|surfboard', 'surfboard', 'surfboard', 'n.', 'A2', 50, 'A long board we stand or lie on to ride waves.', 'She waxed her surfboard before hitting the waves.', 1180),
  (1176, 'A2|exercise-and-matches|surfing', 'surfing', 'surfing', 'n.', 'A2', 50, 'The sport or activity of riding a surfboard to move on waves.', 'Surfing is very popular in California and Hawaii.', 1181),
  (1177, 'A2|exercise-and-matches|registration', 'registration', 'registration', 'n.', 'A2', 50, 'The act of putting someone''s name or information on an official list.', 'Team registration opens next week.', 1170),
  (1178, 'A2|exercise-and-matches|membership', 'membership', 'membership', 'n.', 'A2', 50, 'The state of belonging to a group, organization, etc.', 'I renewed my gym membership for another year.', 1163),
  (1179, 'A2|exercise-and-matches|practice', 'practice', 'practice', 'v.', 'A2', 50, 'To do or play something many times to become good at it.', 'The band will practice on Tuesday night.', 1166),
  (1180, 'A2|exercise-and-matches|team', 'team', 'team', 'n.', 'A2', 50, 'A group of people who compete against another group in a sport or game.', 'Our team won the local football cup.', 1182),
  (1181, 'A2|exercise-and-matches|fan', 'fan', 'fan', 'n.', 'A2', 50, 'Someone with a strong interest in and enthusiasm for a sport, team, or athlete.', 'He is a huge fan of Manchester United.', 1156),
  (1182, 'A2|exercise-and-matches|record', 'record', 'record', 'n.', 'A2', 50, 'The best performance or result, or the highest/lowest level ever reached, especially in sport.', 'She broke the world record for the high jump.', 1169),
  (1183, 'A2|exercise-and-matches|net', 'net', 'net', 'n.', 'A2', 50, 'The barrier in sports such as tennis or at the back of goalposts in soccer or hockey.', 'He hit the tennis ball straight into the net.', 1164),
  (1184, 'A2|exercise-and-matches|prize', 'prize', 'prize', 'n.', 'A2', 50, 'Anything given as a reward to someone who has done very good work or won a contest.', 'The first prize is a hundred dollars.', 1167),
  (1185, 'A2|family-and-friends|daddy', 'daddy', 'daddy', 'n.', 'A2', 51, 'An informal or intimate name for fathers, especially used by children.', 'Daddy, can we play a game?', 1189),
  (1186, 'A2|family-and-friends|mommy', 'mommy', 'mommy', 'n.', 'A2', 51, 'An informal or intimate name for mothers, especially used by children.', 'Her mommy hugged her tightly.', 1206),
  (1187, 'A2|family-and-friends|grandparent', 'grandparent', 'grandparent', 'n.', 'A2', 51, 'Someone who is the parent of our mother or father.', 'I love my grandparents.', 1196),
  (1188, 'A2|family-and-friends|grandpa', 'grandpa', 'grandpa', 'n.', 'A2', 51, 'The father of our mother or father.', 'My grandpa is sixty years old.', 1195),
  (1189, 'A2|family-and-friends|grandma', 'grandma', 'grandma', 'n.', 'A2', 51, 'The mother of our mother or father.', 'Grandma baked a cake for us.', 1194),
  (1190, 'A2|family-and-friends|granddaughter', 'granddaughter', 'granddaughter', 'n.', 'A2', 51, 'The daughter of our son or daughter.', 'She is a lovely granddaughter.', 1193),
  (1191, 'A2|family-and-friends|grandson', 'grandson', 'grandson', 'n.', 'A2', 51, 'The son of our son or daughter.', 'His grandson plays soccer.', 1197),
  (1192, 'A2|family-and-friends|group', 'group', 'group', 'n.', 'A2', 51, 'A number of people or things that are connected or in the same place.', 'A group of students waited.', 1198),
  (1193, 'A2|family-and-friends|guest', 'guest', 'guest', 'n.', 'A2', 51, 'Someone invited to visit a home or attend an event.', 'We have a guest for dinner.', 1200),
  (1194, 'A2|family-and-friends|dude', 'dude', 'dude', 'n.', 'A2', 51, 'A casual word used to refer to a man.', 'What''s up, dude?', 1191),
  (1195, 'A2|family-and-friends|guy', 'guy', 'guy', 'n.', 'A2', 51, 'A person, typically male.', 'Who is that guy?', 1201),
  (1196, 'A2|family-and-friends|neighbor', 'neighbor', 'neighbor', 'n.', 'A2', 51, 'Someone living very close to us.', 'My neighbor is very friendly.', 1207),
  (1197, 'A2|family-and-friends|surname', 'surname', 'surname', 'n.', 'A2', 51, 'The family name shared with parents, following the first name.', 'His surname is Smith.', 1210),
  (1198, 'A2|family-and-friends|family-name', 'family name', 'family name', 'n.', 'A2', 51, 'The name shared with parents, following the first name.', 'Please write your family name.', 1192),
