  (1206, 'A2|family-and-friends|care', 'care', 'care', 'v.', 'A2', 51, 'To consider someone or something important and feel concern for them.', 'I care about you.', 1187),
  (1207, 'A2|family-and-friends|marry', 'marry', 'marry', 'v.', 'A2', 51, 'To become someone''s husband or wife.', 'Will you marry me?', 1203),
