  (1213, 'A2|flowers-fruits-and-nuts|farm', 'farm', 'farm', 'n.', 'A2', 52, 'An area of land and its buildings used for growing crops or keeping animals.', 'He works on a large dairy farm.', 1217),
  (1214, 'A2|flowers-fruits-and-nuts|farming', 'farming', 'farming', 'n.', 'A2', 52, 'The activity of working on a farm and growing crops or producing animal products.', 'Farming is hard physical work.', 1218),
