  (1219, 'A2|flowers-fruits-and-nuts|produce', 'produce', 'produce', 'v.', 'A2', 52, 'To raise or grow something naturally in large numbers; to make something using raw materials.', 'The trees produce a lot of fruit this year.', 1235),
  (1220, 'A2|flowers-fruits-and-nuts|feed', 'feed', 'feed', 'v.', 'A2', 52, 'To give food to a person or animal.', 'The farmer has to feed the chickens.', 1219),
