  (2369, 'B1|business-and-workplace|contract', 'contract', 'contract', 'n.', 'B1', 88, 'An official agreement specifying duties of each involved side.', 'You must sign the contract before starting work.', 2363),
  (2370, 'B1|business-and-workplace|business-plan', 'business plan', 'business plan', 'n.', 'B1', 88, 'A document outlining company goals and strategies for achieving them.', 'The bank needs to see your business plan.', 2358),
  (2371, 'B1|business-and-workplace|interview', 'interview', 'interview', 'v.', 'B1', 88, 'To ask questions to determine someone''s suitability for a job or course.', 'The manager will interview you tomorrow.', 2373),
  (2372, 'B1|business-and-workplace|interview#2', 'interview', 'interview', 'n.', 'B1', 88, 'A meeting where someone is questioned for a job or course.', 'I am nervous about my job interview.', 2374),
  (2373, 'B1|business-and-workplace|competition', 'competition', 'competition', 'n.', 'B1', 88, 'The act of striving to achieve goals better than others.', 'There is strong competition in the software market.', 2361),
  (2374, 'B1|business-and-workplace|opportunity', 'opportunity', 'opportunity', 'n.', 'B1', 88, 'A chance or situation that makes achieving something easier.', 'This job is a great opportunity for you.', 2382),
  (2375, 'B1|business-and-workplace|professional', 'professional', 'professional', 'adj.', 'B1', 88, 'Doing an activity as a job rather than just for pleasure.', 'He hired a professional photographer.', 2386),
  (2376, 'B1|business-and-workplace|commercial', 'commercial', 'commercial', 'adj.', 'B1', 88, 'Related to buying, selling, or exchanging goods and services.', 'The building is used for commercial purposes.', 2360),
  (2377, 'B1|business-and-workplace|unemployment', 'unemployment', 'unemployment', 'n.', 'B1', 88, 'The state of not having a job while seeking work.', 'The government promised to reduce unemployment.', 2395),
  (2378, 'B1|business-and-workplace|financial', 'financial', 'financial', 'adj.', 'B1', 88, 'Related to money, banking, or economic management.', 'The company has serious financial problems.', 2368),
  (2379, 'B1|business-and-workplace|supply', 'supply', 'supply', 'n.', 'B1', 88, 'Necessary items such as food, clothes, or medicine for people.', 'We have a large supply of fresh water.', 2392),
  (2380, 'B1|business-and-workplace|demand', 'demand', 'demand', 'n.', 'B1', 88, 'The desire or need for particular goods or services.', 'There is a high demand for new houses.', 2366),
  (2381, 'B1|business-and-workplace|service', 'service', 'service', 'n.', 'B1', 88, 'Work done for the benefit of others by people or organizations.', 'The hotel provides excellent customer service.', 2390),
  (2382, 'B1|business-and-workplace|mine', 'mine', 'mine', 'n.', 'B1', 88, 'A deep hole or tunnel for extracting minerals or resources.', 'The workers went deep into the coal mine.', 2378),
  (2383, 'B1|business-and-workplace|plant', 'plant', 'plant', 'n.', 'B1', 88, 'A factory or facility where industrial processes or power generation occur.', 'They opened a new chemical plant.', 2384),
  (2384, 'B1|business-and-workplace|workshop', 'workshop', 'workshop', 'n.', 'B1', 88, 'A building or room where goods are made, repaired, or assembled.', 'He fixes bicycles in his workshop.', 2397),
  (2385, 'B1|business-and-workplace|garage', 'garage', 'garage', 'n.', 'B1', 88, 'A place where vehicles are maintained, repaired, or stored.', 'I left my car at the garage for repairs.', 2370),
  (2386, 'B1|business-and-workplace|headquarters', 'headquarters', 'headquarters', 'n.', 'B1', 88, 'The main offices of a company or organization are located.', 'The bank''s headquarters are in New York.', 2371),
  (2387, 'B1|business-and-workplace|unemployed', 'unemployed', 'unemployed', 'adj.', 'B1', 88, 'Without a job while actively seeking employment opportunities.', 'He has been unemployed for six months.', 2394),
  (2388, 'B1|business-and-workplace|consumer', 'consumer', 'consumer', 'n.', 'B1', 88, 'Someone who purchases and uses goods or services.', 'The new law protects the rights of the consumer.', 2362),
  (2389, 'B1|business-and-workplace|partner', 'partner', 'partner', 'n.', 'B1', 88, 'One of the co-owners sharing expenses, profits, and losses in a business.', 'She is a senior partner at the law firm.', 2383),
  (2390, 'B1|business-and-workplace|qualified', 'qualified', 'qualified', 'adj.', 'B1', 88, 'Having the necessary skills, knowledge, or experience for a task.', 'We need a qualified mechanic to fix this.', 2388),
  (2391, 'B1|business-and-workplace|crew', 'crew', 'crew', 'n.', 'B1', 88, 'A group of people with shared skills participating in a common activity.', 'The flight crew prepared the plane for takeoff.', 2364),
  (2392, 'B1|business-and-workplace|manage', 'manage', 'manage', 'v.', 'B1', 88, 'To be in charge of a team, organization, or department.', 'He has to manage a team of twenty people.', 2376),
  (2393, 'B1|business-and-workplace|resource', 'resource', 'resource', 'n.', 'B1', 88, 'Means such as money, equipment, or personnel available for use.', 'Time is our most valuable resource.', 2389),
  (2394, 'B1|business-and-workplace|firm', 'firm', 'firm', 'n.', 'B1', 88, 'A company or business, often owned by two or more partners.', 'She works for an accounting firm.', 2369),
  (2395, 'B1|business-and-workplace|marketing', 'marketing', 'marketing', 'n.', 'B1', 88, 'The process of selling or advertising a product, including research.', 'We need a better marketing strategy.', 2377),
  (2396, 'B1|business-and-workplace|working', 'working', 'working', 'adj.', 'B1', 88, 'Having an occupation that provides a salary or regular income.', 'She is a working mother.', 2396),
  (2397, 'B1|business-and-workplace|skilled', 'skilled', 'skilled', 'adj.', 'B1', 88, 'Possessing the experience or knowledge to perform tasks competently.', 'The job requires highly skilled workers.', 2391),
  (2398, 'B1|city-and-the-countryside|cafe', 'cafe', 'cafe', 'n.', 'B1', 89, 'Small restaurant selling drinks and light meals daily.', 'We met at the small cafe for coffee and cake.', 2399),
  (2399, 'B1|city-and-the-countryside|gallery', 'gallery', 'gallery', 'n.', 'B1', 89, 'Place where artworks are displayed or sold publicly.', 'The art gallery is displaying a new collection of modern paintings.', 2407),
  (2400, 'B1|city-and-the-countryside|nightclub', 'nightclub', 'nightclub', 'n.', 'B1', 89, 'Venue open at night for dancing, eating, drinking.', 'The loud music from the nightclub kept the neighbors awake.', 2414)
insert into public.vocab_senses (id, source_key, word, word_norm, pos, level, category_id, meaning, example, sort) values
  (2401, 'B1|city-and-the-countryside|fire-station', 'fire station', 'fire station', 'n.', 'B1', 89, 'Building housing firefighters and emergency firefighting equipment.', 'The bright red fire trucks are parked inside the fire station.', 2406),
  (2402, 'B1|city-and-the-countryside|gym', 'gym', 'gym', 'n.', 'B1', 89, 'Place equipped for exercise, sports, or physical training.', 'He works out at the gym for an hour every day.', 2409),
  (2403, 'B1|city-and-the-countryside|playground', 'playground', 'playground', 'n.', 'B1', 89, 'Outdoor area designed for children to play safely.', 'The kids are having fun on the swings at the playground.', 2421),
  (2404, 'B1|city-and-the-countryside|barbershop', 'barbershop', 'barbershop', 'n.', 'B1', 89, 'Shop where men receive haircuts and grooming services.', 'He went to the local barbershop to get a quick haircut.', 2398),
  (2405, 'B1|city-and-the-countryside|urban', 'urban', 'urban', 'adj.', 'B1', 89, 'Relating to city structures, populations, and city life.', 'The government is trying to solve the problems of urban decay.', 2429),
  (2406, 'B1|city-and-the-countryside|suburb', 'suburb', 'suburb', 'n.', 'B1', 89, 'Residential area located outside a central city location.', 'They live in a quiet, leafy suburb outside of the capital.', 2427),
  (2407, 'B1|city-and-the-countryside|outskirts', 'outskirts', 'outskirts', 'n.', 'B1', 89, 'Outer regions or edges of a town or city.', 'They built a new shopping center on the outskirts of town.', 2416),
  (2408, 'B1|city-and-the-countryside|uptown', 'uptown', 'uptown', 'n.', 'B1', 89, 'Upper or more affluent section of a city or town.', 'She lives in an expensive apartment in the uptown district.', 2428),
  (2409, 'B1|city-and-the-countryside|inner-city', 'inner city', 'inner city', 'n.', 'B1', 89, 'Central city area often experiencing social or economic problems.', 'The charity works to help poor families in the inner city.', 2412),
  (2410, 'B1|city-and-the-countryside|community', 'community', 'community', 'n.', 'B1', 89, 'Group of people living together in the same area.', 'The local community organized a festival in the public park.', 2400),
  (2411, 'B1|city-and-the-countryside|commuter', 'commuter', 'commuter', 'n.', 'B1', 89, 'Person who regularly travels to work from home area.', 'The early morning train is always packed with tired commuters.', 2401),
  (2412, 'B1|city-and-the-countryside|population', 'population', 'population', 'n.', 'B1', 89, 'Total number of people living in a specific area.', 'The population of the city has grown rapidly in recent years.', 2422),
  (2413, 'B1|city-and-the-countryside|housing', 'housing', 'housing', 'n.', 'B1', 89, 'Buildings where people live, including condition and type.', 'There is a desperate need for more affordable housing in London.', 2411),
  (2414, 'B1|city-and-the-countryside|parking-lot', 'parking lot', 'parking lot', 'n.', 'B1', 89, 'Designated area for leaving or parking vehicles safely.', 'We left the car in the huge supermarket parking lot.', 2418),
  (2415, 'B1|city-and-the-countryside|road-sign', 'road sign', 'road sign', 'n.', 'B1', 89, 'Sign providing information or warnings to vehicle drivers.', 'Pay attention to the road sign warning of a sharp curve.', 2423),
  (2416, 'B1|city-and-the-countryside|pedestrian', 'pedestrian', 'pedestrian', 'n.', 'B1', 89, 'Person traveling on foot rather than using transportation.', 'Cars must always stop to let a pedestrian cross the street.', 2419),
  (2417, 'B1|city-and-the-countryside|street-light', 'street light', 'street light', 'n.', 'B1', 89, 'Pole with lamp providing illumination along streets or roads.', 'The broken street light made the narrow road very dark.', 2426),
  (2418, 'B1|city-and-the-countryside|lane', 'lane', 'lane', 'n.', 'B1', 89, 'Narrow road part or countryside path for vehicles.', 'The fast cars must stay in the left highway lane.', 2413),
  (2419, 'B1|city-and-the-countryside|overpass', 'overpass', 'overpass', 'n.', 'B1', 89, 'Bridge allowing passage over another road or obstacle.', 'The traffic moves smoothly across the new concrete overpass.', 2417),
  (2420, 'B1|city-and-the-countryside|crossroad', 'crossroad', 'crossroad', 'n.', 'B1', 89, 'Point where two or more roads intersect each other.', 'You should turn right when you reach the next major crossroad.', 2403),
  (2421, 'B1|city-and-the-countryside|farmland', 'farmland', 'farmland', 'n.', 'B1', 89, 'Land cultivated or used for growing crops or livestock.', 'The government wants to build a highway straight through the farmland.', 2405),
  (2422, 'B1|city-and-the-countryside|grassland', 'grassland', 'grassland', 'n.', 'B1', 89, 'Large open area predominantly covered with grass vegetation.', 'The wild horses ran freely across the vast African grassland.', 2408),
  (2423, 'B1|city-and-the-countryside|county', 'county', 'county', 'n.', 'B1', 89, 'US administrative division with local government authority.', 'She was elected as the leader of the local county council.', 2402),
  (2424, 'B1|city-and-the-countryside|orchard', 'orchard', 'orchard', 'n.', 'B1', 89, 'Enclosed land used primarily for growing fruit trees.', 'We spent the afternoon picking fresh apples in the apple orchard.', 2415),
  (2425, 'B1|city-and-the-countryside|well', 'well', 'well', 'n.', 'B1', 89, 'Deep hole dug to access water, oil, or resources.', 'The villagers had to dig a new well for drinking water.', 2430),
  (2426, 'B1|city-and-the-countryside|pizzeria', 'pizzeria', 'pizzeria', 'n.', 'B1', 89, 'Restaurant specializing in the preparation and sale of pizzas.', 'Let''s grab dinner at the new Italian pizzeria down the street.', 2420),
  (2427, 'B1|city-and-the-countryside|dam', 'dam', 'dam', 'n.', 'B1', 89, 'Wall constructed to hold or control water for power.', 'The massive dam provides electricity for the entire surrounding region.', 2404),
  (2428, 'B1|city-and-the-countryside|sidewalk', 'sidewalk', 'sidewalk', 'n.', 'B1', 89, 'Path alongside a street for pedestrians to safely walk.', 'You are not allowed to ride your bicycle on the sidewalk.', 2424),
  (2429, 'B1|city-and-the-countryside|homeland', 'homeland', 'homeland', 'n.', 'B1', 89, 'Place where a person or people feel deep connection.', 'After ten years abroad, he finally returned to his beloved homeland.', 2410),
  (2430, 'B1|city-and-the-countryside|square', 'square', 'square', 'n.', 'B1', 89, 'Open public area where streets intersect in a town.', 'Hundreds of people gathered in the main city square for celebrations.', 2425),
  (2431, 'B1|common-adverbs|about', 'about', 'about', 'adv.', 'B1', 90, 'Used with numbers to show an approximate, not exact, amount.', 'The journey to the city will take about two hours by fast train.', 2431),
  (2432, 'B1|common-adverbs|ago', 'ago', 'ago', 'adv.', 'B1', 90, 'Used to indicate how much time passed before now.', 'The dinosaurs died out completely millions of years ago.', 2433),
  (2433, 'B1|common-adverbs|all', 'all', 'all', 'adv.', 'B1', 90, 'To the complete or full possible degree.', 'She was dressed all in black for the formal evening party.', 2434),
  (2434, 'B1|common-adverbs|anymore', 'anymore', 'anymore', 'adv.', 'B1', 90, 'Used to show something no longer happens or exists.', 'We don''t live in that tiny old apartment anymore.', 2435),
  (2435, 'B1|common-adverbs|anyway', 'anyway', 'anyway', 'adv.', 'B1', 90, 'Used without regard to a particular situation or detail.', 'It is raining heavily, but we are going to the match anyway.', 2436),
  (2436, 'B1|common-adverbs|apart', 'apart', 'apart', 'adv.', 'B1', 90, 'At a distance from each other in space.', 'The two small towns are located exactly fifty miles apart.', 2437),
  (2437, 'B1|common-adverbs|certainly', 'certainly', 'certainly', 'adv.', 'B1', 90, 'In a confident manner allowing no doubt or hesitation.', 'She will certainly pass the exam because she studied incredibly hard.', 2438),
  (2438, 'B1|common-adverbs|clearly', 'clearly', 'clearly', 'adv.', 'B1', 90, 'In a way that is easy to understand.', 'Please speak very clearly into the microphone so everyone can hear you.', 2439),
  (2439, 'B1|common-adverbs|commonly', 'commonly', 'commonly', 'adv.', 'B1', 90, 'In most cases, as a usual or standard practice.', 'This specific type of flower is commonly found in tropical climates.', 2440),
  (2440, 'B1|common-adverbs|correctly', 'correctly', 'correctly', 'adv.', 'B1', 90, 'In a right way without errors or mistakes.', 'Make sure you answer all the test questions completely and correctly.', 2441),
  (2441, 'B1|common-adverbs|definitely', 'definitely', 'definitely', 'adv.', 'B1', 90, 'In a way that leaves no doubt.', 'I will definitely be at the party tonight, I promise.', 2442),
  (2442, 'B1|common-adverbs|double', 'double', 'double', 'adv.', 'B1', 90, 'To twice the amount, degree, or intensity.', 'The population of the city has grown double in just ten years.', 2443),
  (2443, 'B1|common-adverbs|each', 'each', 'each', 'adv.', 'B1', 90, 'Used to refer to every individual item separately.', 'The expensive concert tickets cost fifty dollars each.', 2444),
  (2444, 'B1|common-adverbs|effectively', 'effectively', 'effectively', 'adv.', 'B1', 90, 'In a way that produces the intended result.', 'The new medicine works highly effectively to quickly cure the painful disease.', 2445),
  (2445, 'B1|common-adverbs|enough', 'enough', 'enough', 'adv.', 'B1', 90, 'To a sufficient degree for a particular purpose.', 'The water is finally warm enough for us to go swimming safely.', 2446),
  (2446, 'B1|common-adverbs|equally', 'equally', 'equally', 'adv.', 'B1', 90, 'To the same degree or amount.', 'The generous prize money was divided equally among all the winning team members.', 2447),
  (2447, 'B1|common-adverbs|even', 'even', 'even', 'adv.', 'B1', 90, 'Used to emphasize something surprising or unexpected.', 'The weather is incredibly cold today, even for the middle of deep winter.', 2448),
  (2448, 'B1|common-adverbs|first', 'first', 'first', 'adv.', 'B1', 90, 'Before anyone or anything else in order.', 'We must finish eating dinner first, and then we can watch the movie.', 2449),
  (2449, 'B1|common-adverbs|frequently', 'frequently', 'frequently', 'adv.', 'B1', 90, 'Happening often with short intervals between times.', 'The old bus breaks down very frequently on this difficult, bumpy road.', 2450),
  (2450, 'B1|common-adverbs|fully', 'fully', 'fully', 'adv.', 'B1', 90, 'To the greatest possible extent or degree.', 'You must be fully prepared before attempting to climb the dangerous mountain.', 2451),
  (2451, 'B1|common-adverbs|hardly', 'hardly', 'hardly', 'adv.', 'B1', 90, 'To a very small or minimal degree.', 'I was so incredibly tired that I could hardly keep my eyes open.', 2452),
  (2452, 'B1|common-adverbs|heavily', 'heavily', 'heavily', 'adv.', 'B1', 90, 'To a great or serious extent.', 'The damaged ship was leaning heavily to one side in the rough ocean.', 2453),
  (2453, 'B1|common-adverbs|however', 'however', 'however', 'adv.', 'B1', 90, 'Used to introduce a statement that contrasts earlier.', 'The test was hard; however, almost every single student managed to pass.', 2454),
  (2454, 'B1|common-adverbs|incredibly', 'incredibly', 'incredibly', 'adv.', 'B1', 90, 'To an extremely great or surprising degree.', 'The new sports car is incredibly fast and extremely expensive to buy.', 2455),
  (2455, 'B1|common-adverbs|indeed', 'indeed', 'indeed', 'adv.', 'B1', 90, 'Used to strongly emphasize or confirm something.', 'Thank you very much indeed for all your wonderful help today.', 2456),
  (2456, 'B1|common-adverbs|least', 'least', 'least', 'adv.', 'B1', 90, 'To the lowest possible degree or amount.', 'That was probably the least interesting movie I have ever seen in my life.', 2457),
  (2457, 'B1|common-adverbs|mainly', 'mainly', 'mainly', 'adv.', 'B1', 90, 'Mostly or primarily in most situations.', 'The enthusiastic audience consisted mainly of teenagers and young university students.', 2458),
  (2458, 'B1|common-adverbs|mostly', 'mostly', 'mostly', 'adv.', 'B1', 90, 'In a way involving the majority of cases.', 'The cloudy sky was mostly clear by the time we reached the beach.', 2459),
  (2459, 'B1|common-adverbs|naturally', 'naturally', 'naturally', 'adv.', 'B1', 90, 'In a logical or expected manner.', 'Naturally, she was extremely upset when she failed the important exam again.', 2460),
  (2460, 'B1|common-adverbs|absolutely', 'absolutely', 'absolutely', 'adv.', 'B1', 90, 'Used to express total agreement or certainty.', 'You are absolutely right; we must leave immediately to catch the train.', 2432),
  (2461, 'B1|common-verbs|request', 'request', 'request', 'v.', 'B1', 91, 'To ask for something politely or formally from others.', 'I would like to formally request a copy of the official police report.', 2463),
  (2462, 'B1|common-verbs|require', 'require', 'require', 'v.', 'B1', 91, 'To need or demand something as necessary for situations.', 'Some highly skilled jobs strictly require you to have a university master''s degree.', 2464),
  (2463, 'B1|common-verbs|revise', 'revise', 'revise', 'v.', 'B1', 91, 'To change something to improve it after feedback received.', 'You should carefully revise your essay before handing it to the strict teacher.', 2467),
  (2464, 'B1|common-verbs|risk', 'risk', 'risk', 'v.', 'B1', 91, 'To put something important in danger of harm occurring.', 'He was willing to bravely risk his own life to save the drowning child.', 2468),
  (2465, 'B1|common-verbs|roll', 'roll', 'roll', 'v.', 'B1', 91, 'To make something move by turning repeatedly over surfaces.', 'The children love to roll the heavy snowball down the steep snowy hill.', 2469),
  (2466, 'B1|common-verbs|scan', 'scan', 'scan', 'v.', 'B1', 91, 'To read text quickly to find information without details.', 'I will quickly scan the long document to find the important names mentioned.', 2471),
  (2467, 'B1|common-verbs|separate', 'separate', 'separate', 'v.', 'B1', 91, 'To divide something from a larger whole into parts.', 'You must carefully separate the white clothes from the colored ones before washing.', 2472),
  (2468, 'B1|common-verbs|set', 'set', 'set', 'v.', 'B1', 91, 'To put something in a specific position carefully there.', 'She carefully set the delicate vase on the high shelf away from children.', 2473),
  (2469, 'B1|common-verbs|signal', 'signal', 'signal', 'v.', 'B1', 91, 'To communicate messages using sounds or movements to others.', 'The policeman used a bright light to clearly signal the cars to stop.', 2474),
  (2470, 'B1|common-verbs|sink', 'sink', 'sink', 'v.', 'B1', 91, 'To go below the surface of liquid or material.', 'The heavy rock will immediately sink to the bottom of the deep lake.', 2475),
  (2471, 'B1|common-verbs|sort', 'sort', 'sort', 'v.', 'B1', 91, 'To organize items into groups by characteristics or criteria.', 'I need to sort these messy documents into alphabetical order before the meeting.', 2478),
  (2472, 'B1|common-verbs|snore', 'snore', 'snore', 'v.', 'B1', 91, 'To breathe noisily through nose while sleeping at night.', 'My grandfather tends to snore very loudly when he falls asleep on the couch.', 2477),
  (2473, 'B1|common-verbs|sniff', 'sniff', 'sniff', 'v.', 'B1', 91, 'To breathe in audibly through the nose to clear.', 'The dog began to excitedly sniff the ground searching for the hidden bone.', 2476),
  (2474, 'B1|common-verbs|stick', 'stick', 'stick', 'v.', 'B1', 91, 'To fix an object to another using adhesive materials.', 'Use this strong glue to firmly stick the broken pieces of wood together.', 2479),
  (2475, 'B1|common-verbs|store', 'store', 'store', 'v.', 'B1', 91, 'To keep something for later use safely in place.', 'Squirrels try to store enough nuts in the trees to survive the winter.', 2480),
  (2476, 'B1|common-verbs|summarize', 'summarize', 'summarize', 'v.', 'B1', 91, 'To give a short version covering main points only.', 'The teacher asked the student to briefly summarize the entire plot of the book.', 2481),
  (2477, 'B1|common-verbs|supply', 'supply', 'supply', 'v.', 'B1', 91, 'To provide necessary items or resources for needs purposes.', 'The charity works hard to constantly supply food and water to the refugees.', 2482),
  (2478, 'B1|common-verbs|survive', 'survive', 'survive', 'v.', 'B1', 91, 'To remain alive after dangerous or difficult events situations.', 'Only a few strong trees managed to actually survive the incredibly destructive hurricane.', 2483),
  (2479, 'B1|common-verbs|switch', 'switch', 'switch', 'v.', 'B1', 91, 'To change completely from one thing to another different.', 'Let''s quickly switch seats so you can look out of the airplane window.', 2484),
  (2480, 'B1|common-verbs|tend', 'tend', 'tend', 'v.', 'B1', 91, 'To be likely to happen in usual ways patterns.', 'Small children generally tend to get very tired and cranky in the afternoon.', 2485),
  (2481, 'B1|common-verbs|translate', 'translate', 'translate', 'v.', 'B1', 91, 'To change words into another language accurately for understanding.', 'Can you please translate this complicated Spanish document into clear English for me?', 2486),
  (2482, 'B1|common-verbs|upset', 'upset', 'upset', 'v.', 'B1', 91, 'To make someone emotionally unhappy or disturbed by actions.', 'Do not tell him the bad news because it will completely upset him.', 2487),
  (2483, 'B1|common-verbs|view', 'view', 'view', 'v.', 'B1', 91, 'To look at something carefully and attentively for details.', 'The public can safely view the famous painting behind thick, secure glass cases.', 2488),
  (2484, 'B1|common-verbs|yawn', 'yawn', 'yawn', 'v.', 'B1', 91, 'To open mouth widely when tired or bored suddenly.', 'The boring lecture made almost every single student yawn loudly in the classroom.', 2494),
  (2485, 'B1|common-verbs|warm', 'warm', 'warm', 'v.', 'B1', 91, 'To increase temperature making someone or something hotter gradually.', 'We sat near the fire to slowly warm our freezing hands after skiing.', 2489),
  (2486, 'B1|common-verbs|warn', 'warn', 'warn', 'v.', 'B1', 91, 'To tell someone about danger before it happens occurs.', 'I tried to strongly warn him about the dangerously icy roads this morning.', 2490),
  (2487, 'B1|common-verbs|waste', 'waste', 'waste', 'v.', 'B1', 91, 'To use something carelessly or excessively without need purpose.', 'You should not waste so much clean water when you wash your car.', 2491),
  (2488, 'B1|common-verbs|wave', 'wave', 'wave', 'v.', 'B1', 91, 'To move hand side to side for greeting attention.', 'She turned back to happily wave goodbye before getting onto the busy train.', 2492),
  (2489, 'B1|common-verbs|wonder', 'wonder', 'wonder', 'v.', 'B1', 91, 'To want to know something or feel curiosity about.', 'I often wonder what happened to my old friends from elementary school nowadays.', 2493),
  (2490, 'B1|common-verbs|pause', 'pause', 'pause', 'v.', 'B1', 91, 'To stop briefly before continuing an activity or process.', 'The speaker had to pause for a moment to take a drink of water.', 2461),
