  (3246, 'B1|money-and-shopping|coin', 'coin', 'coin', 'n.', 'B1', 117, 'A flat, round piece of metal issued by a government as money.', 'He dropped a silver coin into the vending machine.', 3253),
  (3247, 'B1|money-and-shopping|currency', 'currency', 'currency', 'n.', 'B1', 117, 'The system or type of money used by a country.', 'You need to exchange your currency before traveling abroad.', 3255),
  (3248, 'B1|money-and-shopping|discount', 'discount', 'discount', 'n.', 'B1', 117, 'A reduction in the usual price of something.', 'Students can get a discount on cinema tickets.', 3258),
  (3249, 'B1|money-and-shopping|inexpensive', 'inexpensive', 'inexpensive', 'adj.', 'B1', 117, 'Reasonably priced; not costly.', 'We found a nice, inexpensive restaurant for lunch.', 3262),
  (3250, 'B1|money-and-shopping|mall', 'mall', 'mall', 'n.', 'B1', 117, 'A large building or area containing many shops.', 'Teenagers like to hang out at the shopping mall.', 3264),
  (3251, 'B1|money-and-shopping|stall', 'stall', 'stall', 'n.', 'B1', 117, 'A small table, stand, or shop with an open front for selling goods.', 'She bought fresh fruit from a market stall.', 3276),
