  (3256, 'B1|money-and-shopping|product', 'product', 'product', 'n.', 'B1', 117, 'An item created or grown for sale.', 'The company will launch a new software product soon.', 3269),
  (3257, 'B1|money-and-shopping|goods', 'goods', 'goods', 'n.', 'B1', 117, 'Items made or produced for sale.', 'The supermarket sells a wide variety of household goods.', 3261),
  (3258, 'B1|money-and-shopping|checkout', 'checkout', 'checkout', 'n.', 'B1', 117, 'Place in a store where customers pay for purchased items.', 'There was a long line at the supermarket checkout.', 3252),
