  (3260, 'B1|money-and-shopping|owe', 'owe', 'owe', 'v.', 'B1', 117, 'To be responsible for paying back borrowed money.', 'I still owe you five dollars for lunch.', 3266),
  (3261, 'B1|money-and-shopping|credit', 'credit', 'credit', 'n.', 'B1', 117, 'The ability to obtain goods or funds based on trust, allowing deferred payment.', 'We bought the new television on credit.', 3254),
  (3262, 'B1|money-and-shopping|debt', 'debt', 'debt', 'n.', 'B1', 117, 'Money or favor that is owed.', 'He is working hard to pay off his credit card debt.', 3257),
  (3263, 'B1|money-and-shopping|donate', 'donate', 'donate', 'v.', 'B1', 117, 'To freely give money, goods, or food to someone or an organization.', 'People donate warm clothes to charity in the winter.', 3259),
  (3264, 'B1|money-and-shopping|balance', 'balance', 'balance', 'n.', 'B1', 117, 'The amount of money remaining in a bank account.', 'I checked my bank balance before buying the phone.', 3245),
  (3265, 'B1|money-and-shopping|expense', 'expense', 'expense', 'n.', 'B1', 117, 'Money spent to obtain or do something.', 'Buying a house is a major expense for families.', 3260),
  (3266, 'B1|money-and-shopping|value', 'value', 'value', 'n.', 'B1', 117, 'The monetary worth of something.', 'The value of the painting is estimated at one million dollars.', 3280),
