  (3269, 'B1|money-and-shopping|bargain', 'bargain', 'bargain', 'n.', 'B1', 117, 'An item bought at a much lower price than usual.', 'This beautiful jacket was an absolute bargain!', 3246),
  (3270, 'B1|money-and-shopping|tax', 'tax', 'tax', 'n.', 'B1', 117, 'Money paid to the government based on income or sales to fund public services.', 'The government plans to increase the tax on gasoline.', 3278),
  (3271, 'B1|money-and-shopping|possession', 'possession', 'possession', 'n.', 'B1', 117, 'Anything owned by a person at a given time, usually plural.', 'She packed all her personal possessions into one suitcase.', 3268),
  (3272, 'B1|money-and-shopping|belong', 'belong', 'belong', 'v.', 'B1', 117, 'To be the property of someone.', 'Who does this blue umbrella belong to?', 3247),
  (3273, 'B1|money-and-shopping|saving', 'saving', 'saving', 'n.', 'B1', 117, 'Money set aside and not spent.', 'He used all his life savings to start a business.', 3273),
  (3274, 'B1|money-and-shopping|production', 'production', 'production', 'n.', 'B1', 117, 'The process of transforming raw materials into goods for use or sale.', 'The factory increased production to meet customer demand.', 3270),
  (3275, 'B1|money-and-shopping|worth', 'worth', 'worth', 'adj.', 'B1', 117, 'Equivalent to a specified amount of money.', 'That old coin is worth a lot of money today.', 3281),
  (3276, 'B1|money-and-shopping|cut', 'cut', 'cut', 'n.', 'B1', 117, 'A reduction in quantity, size, or amount.', 'The store announced a price cut on all electronics.', 3256),
  (3277, 'B1|money-and-shopping|luxury', 'luxury', 'luxury', 'n.', 'B1', 117, 'Great comfort or pleasure afforded by expensive items or experiences.', 'They stayed in a luxury hotel by the beach.', 3263),
  (3278, 'B1|money-and-shopping|overpriced', 'overpriced', 'overpriced', 'adj.', 'B1', 117, 'Excessively costly relative to value.', 'The food at the airport is completely overpriced.', 3265),
  (3279, 'B1|money-and-shopping|penny', 'penny', 'penny', 'n.', 'B1', 117, 'A unit of currency equal to $1/100$ of a dollar or pound.', 'I don''t have a single penny left in my wallet.', 3267),
  (3280, 'B1|money-and-shopping|check', 'check', 'check', 'n.', 'B1', 117, 'A written form authorizing payment instead of cash.', 'I wrote a check to pay for the electricity bill.', 3251),
  (3281, 'B1|money-and-shopping|sale', 'sale', 'sale', 'n.', 'B1', 117, 'The act or process of selling something.', 'The sale of the property was completed yesterday.', 3272),
  (3282, 'B1|movie-and-theater|action-movie', 'action movie', 'action movie', 'n.', 'B1', 118, 'A movie with exciting fights, chases, and explosive scenes throughout.', 'We went to the cinema to watch a thrilling, fast-paced action movie tonight.', 3282),
  (3283, 'B1|movie-and-theater|animation', 'animation', 'animation', 'n.', 'B1', 118, 'A movie in which characters are drawn or digitally created to move.', 'The colorful 3D computer animation was incredibly popular with all the young children.', 3283),
  (3284, 'B1|movie-and-theater|audition', 'audition', 'audition', 'n.', 'B1', 118, 'A meeting where performers demonstrate skills to get selected for roles.', 'She was extremely nervous before her singing audition for the main theater role.', 3284),
  (3285, 'B1|movie-and-theater|box-office', 'box office', 'box office', 'n.', 'B1', 118, 'The place where tickets for events or movies are sold.', 'You can buy your concert tickets directly at the theater box office outside.', 3285),
  (3286, 'B1|movie-and-theater|cast', 'cast', 'cast', 'n.', 'B1', 118, 'All actors and actresses appearing in a movie, play, or show.', 'The movie features an incredibly talented cast of famous Hollywood actors and actresses.', 3286),
  (3287, 'B1|movie-and-theater|classic', 'classic', 'classic', 'n.', 'B1', 118, 'A highly respected movie, book, or music piece considered valuable.', 'We watched a famous old black-and-white classic on television late last night.', 3287),
  (3288, 'B1|movie-and-theater|clown', 'clown', 'clown', 'n.', 'B1', 118, 'A performer who wears costume and makeup to entertain an audience humorously.', 'The funny circus clown made all the little children laugh out loud constantly.', 3288),
  (3289, 'B1|movie-and-theater|critic', 'critic', 'critic', 'n.', 'B1', 118, 'Someone who evaluates and expresses opinions on art, performances, or creative works.', 'The famous film critic wrote a very harsh review of the terrible new movie.', 3289),
