  (3291, 'B1|movie-and-theater|direct', 'direct', 'direct', 'v.', 'B1', 118, 'To instruct actors and organize scenes in a movie, play, or show.', 'The famous filmmaker plans to direct a brand new historical drama next year.', 3292),
  (3292, 'B1|movie-and-theater|dramatic', 'dramatic', 'dramatic', 'adj.', 'B1', 118, 'Related to acting, theater performances, or emotionally intense situations.', 'She gave a highly emotional and incredibly dramatic performance in the school play.', 3293),
  (3293, 'B1|movie-and-theater|edit', 'edit', 'edit', 'v.', 'B1', 118, 'To arrange or remove parts of a movie, show, or other production.', 'It takes months to carefully edit a feature-length film before releasing it publicly.', 3294),
  (3294, 'B1|movie-and-theater|editor', 'editor', 'editor', 'n.', 'B1', 118, 'The person in charge of arranging or cutting scenes in a production.', 'The skilled film editor cut out three boring scenes to make the movie faster.', 3295),
