  (3296, 'B1|movie-and-theater|film-festival', 'film festival', 'film festival', 'n.', 'B1', 118, 'An event showcasing new movies from various countries to the public.', 'Her amazing new movie won the top prize at the international film festival.', 3297),
  (3297, 'B1|movie-and-theater|genre', 'genre', 'genre', 'n.', 'B1', 118, 'A style of art, literature, or film with distinct characteristics.', 'My absolute favorite movie genre is definitely science fiction because I love space.', 3298),
  (3298, 'B1|movie-and-theater|part', 'part', 'part', 'n.', 'B1', 118, 'The specific role assigned to an actor in a movie or play.', 'He proudly played the part of the brave hero in the exciting new movie.', 3302),
  (3299, 'B1|movie-and-theater|produce', 'produce', 'produce', 'v.', 'B1', 118, 'To provide money and oversee the creation of a movie, play, or show.', 'It costs millions of dollars to officially produce a major Hollywood action film.', 3303),
  (3300, 'B1|movie-and-theater|melodrama', 'melodrama', 'melodrama', 'n.', 'B1', 118, 'A dramatic work with exaggerated emotions, intense conflicts, and emotional appeal.', 'The television show is a classic melodrama full of crying, secrets, and tragedy.', 3299)
