  (3303, 'B1|movie-and-theater|script', 'script', 'script', 'n.', 'B1', 118, 'The written text that a movie, play, or show is based upon for performance.', 'The actors spent hours reading the script together before they started filming the scenes.', 3304),
  (3304, 'B1|movie-and-theater|scriptwriter', 'scriptwriter', 'scriptwriter', 'n.', 'B1', 118, 'A person whose job is writing the story for a movie, play, or show.', 'The talented scriptwriter won an award for the brilliant story he created.', 3305),
