  (3315, 'B1|movie-and-theater|villain', 'villain', 'villain', 'n.', 'B1', 118, 'The main character in a story or movie who is bad or evil.', 'The evil villain tried to completely destroy the city before the hero stopped him.', 3315),
  (3316, 'B1|movie-and-theater|western', 'western', 'western', 'n.', 'B1', 118, 'A story or movie about cowboys, settlers, and adventures in the American West.', 'He loves watching an old classic western featuring cowboys riding horses and shooting guns.', 3316),
