  (3557, 'B1|quantities-and-containers|basket', 'Basket', 'basket', 'n.', 'B1', 126, 'A container with handle used for carrying items.', 'She carried the fresh fruit in a woven wooden basket from the market.', 3528),
  (3558, 'B1|quantities-and-containers|bucket', 'Bucket', 'bucket', 'n.', 'B1', 126, 'A wide container with handle for carrying liquids.', 'He filled the plastic bucket with warm, soapy water to wash the car.', 3530),
