  (3572, 'B1|religion-and-festivals|christmas-carol', 'Christmas carol', 'christmas carol', 'n.', 'B1', 127, 'Religious or festive song sung during Christmas season.', 'The choir stood in the snow and sang a beautiful Christmas carol.', 3580),
  (3573, 'B1|religion-and-festivals|eggnog', 'Eggnog', 'eggnog', 'n.', 'B1', 127, 'Drink made from milk, eggs, sugar, often spiked.', 'We drank warm, sweet eggnog by the fire on winter nights.', 3587),
