insert into public.vocab_senses (id, source_key, word, word_norm, pos, level, category_id, meaning, example, sort) values
  (3901, 'B1|time|continuously', 'continuously', 'continuously', 'adv.', 'B1', 137, 'Without any pause or break over a period.', 'It rained continuously for three entire days, causing the local river to completely flood.', 3900),
  (3902, 'B1|time|ahead-of-time', 'ahead of time', 'ahead of time', 'adv.', 'B1', 137, 'Before the scheduled or expected moment occurs.', 'We finished the complex project significantly ahead of time, impressing our demanding boss.', 3894),
  (3903, 'B1|time|late', 'late', 'late', 'adj.', 'B1', 137, 'Occurring after the expected or usual time.', 'He apologized profusely for being twenty minutes late to the very important business meeting.', 3915),
  (3904, 'B1|time|last', 'last', 'last', 'v.', 'B1', 137, 'To continue in existence over a period of time.', 'The entertaining movie will last for exactly two hours and fifteen minutes.', 3914),
  (3905, 'B1|time|take', 'take', 'take', 'v.', 'B1', 137, 'To require a specific amount of time for completion.', 'It will take me approximately thirty minutes to securely drive to the airport.', 3928),
