  (3907, 'B1|time|throughout', 'throughout', 'throughout', 'adv.', 'B1', 137, 'During the entire period of an event or process.', 'It rained heavily and persistently throughout the entire duration of the long, dark night.', 3930),
  (3908, 'B1|time|sudden', 'sudden', 'sudden', 'adj.', 'B1', 137, 'Happening quickly and unexpectedly without prior warning.', 'There was a very sudden, loud noise that completely startled the sleeping dog.', 3927),
  (3909, 'B1|time|regularly', 'regularly', 'regularly', 'adv.', 'B1', 137, 'Happening at predictable and equal time intervals.', 'You should exercise regularly to maintain a healthy heart and strong physical body.', 3926),
  (3910, 'B1|time|regular', 'regular', 'regular', 'adj.', 'B1', 137, 'Occurring frequently or according to a routine.', 'She makes regular visits to the dentist to ensure her teeth remain perfectly healthy.', 3925),
  (3911, 'B1|time|immediate', 'immediate', 'immediate', 'adj.', 'B1', 137, 'Happening or existing at the present instant.', 'The dangerous situation requires our absolute and immediate attention before it gets significantly worse.', 3910),
  (3912, 'B1|time|eventually', 'eventually', 'eventually', 'adv.', 'B1', 137, 'After a series of events or extended period.', 'If you keep practicing diligently, you will eventually learn how to play the guitar.', 3904),
  (3913, 'B1|time|afterward', 'afterward', 'afterward', 'adv.', 'B1', 137, 'Following a specific event or action in time.', 'We had dinner together and went to the cinema to watch a movie afterward.', 3892),
