  (6004, 'B2|time|instant', 'instant', 'instant', 'adj.', 'B2', 195, 'Happening immediately or accomplished very quickly without delay.', 'The instant coffee dissolved in hot water.', 6000),
  (6005, 'B2|time|for-the-moment', 'for the moment', 'for the moment', 'adv.', 'B2', 195, 'At present time, situation may change soon thereafter.', 'For the moment, we are safe.', 5997),
