  (6854, 'C1|feelings|agitated', 'agitated', 'agitated', 'adj.', 'C1', 219, 'Nervous, restless, or unable to think clearly because disturbed.', 'The dog grew agitated when the thunderstorm began.', 6851),
  (6855, 'C1|feelings|frantic', 'frantic', 'frantic', 'adj.', 'C1', 219, 'Wildly anxious, hurried, or panicked, often uncontrolled emotionally.', 'She made frantic calls to the hospital after her son''s accident.', 6873),
  (6856, 'C1|feelings|broken', 'broken', 'broken', 'adj.', 'C1', 219, 'Weakened physically or mentally, often from prolonged suffering.', 'The years of isolation had left him emotionally broken.', 6857),
  (6857, 'C1|feelings|disturbing', 'disturbing', 'disturbing', 'adj.', 'C1', 219, 'Causing strong discomfort, worry, unease, or emotional disturbance.', 'The disturbing images in the film stayed with me for days.', 6869),
  (6858, 'C1|feelings|disgusted', 'disgusted', 'disgusted', 'adj.', 'C1', 219, 'Feeling intense dislike, revulsion, or strong moral disapproval.', 'She was disgusted by the unsanitary conditions in the restaurant kitchen.', 6865),
  (6859, 'C1|feelings|lovable', 'lovable', 'lovable', 'adj.', 'C1', 219, 'Possessing qualities that inspire warmth, affection, or fondness.', 'The puppy''s lovable personality made it the favorite of the litter.', 6883),
