  (6869, 'C1|feelings|appalled', 'appalled', 'appalled', 'adj.', 'C1', 219, 'Shocked or horrified by something deeply unpleasant or offensive.', 'The public was appalled by the politician''s racist remarks.', 6852),
  (6870, 'C1|feelings|horrified', 'horrified', 'horrified', 'adj.', 'C1', 219, 'Feeling intense fear, shock, or disgust at something.', 'She was horrified when she saw the car accident unfold before her.', 6879),
  (6871, 'C1|feelings|disillusioned', 'disillusioned', 'disillusioned', 'adj.', 'C1', 219, 'Disappointed because reality is less worthy or ideal than expected.', 'After the scandal, many voters became disillusioned with the political system.', 6866),
  (6872, 'C1|feelings|distressed', 'distressed', 'distressed', 'adj.', 'C1', 219, 'Experiencing extreme anxiety, pain, or emotional suffering intensely.', 'The distressed family searched for their lost dog for days.', 6867),
