  (6881, 'C1|feelings|self‑conscious', 'self‑conscious', 'self‑conscious', 'adj.', 'C1', 219, 'Worried or embarrassed about appearance, behavior, or impression.', 'He felt self‑conscious about his accent when speaking in public.', 6886),
  (6882, 'C1|feelings|sentimental', 'sentimental', 'sentimental', 'adj.', 'C1', 219, 'Expressing tender emotions often exaggerated or nostalgic feelings.', 'She kept the old love letters for sentimental reasons.', 6887),
