  (7153, 'C1|identity-and-society|primitive', 'primitive', 'primitive', 'adj.', 'C1', 225, 'Related to a society without modern industry or advanced technology.', 'The tribe used primitive tools made of stone and wood.', 7145),
  (7154, 'C1|identity-and-society|hillbilly', 'hillbilly', 'hillbilly', 'n.', 'C1', 225, 'Person living far from towns, considered uneducated or backward.', 'The derogatory term "hillbilly" is often used as a stereotype.', 7134),
  (7155, 'C1|integral-verbs|applaud', 'applaud', 'applaud', 'v.', 'C1', 226, 'To clap hands as a sign of approval or praise.', 'The audience rose to their feet to applaud the virtuoso pianist''s performance.', 7155),
