  (7164, 'C1|integral-verbs|circulate', 'circulate', 'circulate', 'v.', 'C1', 226, 'To constantly move around a gas, liquid, or air inside space.', 'The ceiling fan helps circulate warm air throughout the room in winter.', 7159),
  (7165, 'C1|integral-verbs|descend', 'descend', 'descend', 'v.', 'C1', 226, 'To move downward toward a lower level or position.', 'The hikers began to descend the mountain as the sun started to set.', 7164),
