  (7168, 'C1|integral-verbs|filter', 'filter', 'filter', 'v.', 'C1', 226, 'To pass gas, liquid, or light through something removing unwanted substances.', 'The coffee machine filters the water to remove impurities before brewing.', 7170),
  (7169, 'C1|integral-verbs|forge', 'forge', 'forge', 'v.', 'C1', 226, 'To shape or create metal by heating and hammering into form.', 'The blacksmith forged a custom iron gate for the old mansion.', 7171),
  (7170, 'C1|integral-verbs|grasp', 'grasp', 'grasp', 'v.', 'C1', 226, 'To take and tightly hold something with your hand.', 'She grasped the rail firmly as the train suddenly jerked forward.', 7173),
  (7171, 'C1|integral-verbs|grip', 'grip', 'grip', 'v.', 'C1', 226, 'To firmly hold or secure an object to prevent movement.', 'The rock climber gripped the tiny ledge with her fingertips.', 7174),
  (7172, 'C1|integral-verbs|preside', 'preside', 'preside', 'v.', 'C1', 226, 'To act in an authoritative role during meeting or ceremony.', 'The chief justice presided over the landmark Supreme Court case.', 7182),
  (7173, 'C1|integral-verbs|resemble', 'resemble', 'resemble', 'v.', 'C1', 226, 'To have a similar appearance or characteristic to someone else.', 'The ancient fossil closely resembles modern lizards, suggesting evolutionary continuity.', 7184),
