  (7175, 'C1|integral-verbs|slam', 'slam', 'slam', 'v.', 'C1', 226, 'To forcefully shut or close a door, lid, or other object.', 'He slammed the car door in frustration after the argument.', 7186),
  (7176, 'C1|integral-verbs|stun', 'stun', 'stun', 'v.', 'C1', 226, 'To temporarily render someone unconscious or immobile by force.', 'The boxer delivered a punch that stunned his opponent for several seconds.', 7188),
