  (7208, 'C1|language-components|intonation', 'intonation', 'intonation', 'n.', 'C1', 227, 'Rising and falling pitch of voice during spoken language.', 'Rising intonation at the end of a sentence often signals a question in English.', 7206),
  (7209, 'C1|language-components|dialect', 'dialect', 'dialect', 'n.', 'C1', 227, 'Regional or social form of language differing slightly from standard.', 'The southern dialect of American English includes unique words and pronunciation.', 7196),
