  (7804, 'C1|time|prospective', 'prospective', 'prospective', 'adj.', 'C1', 243, 'Likely to become a reality in the future.', 'The agent showed the house to several prospective buyers.', 7809),
  (7805, 'C1|time|simultaneous', 'simultaneous', 'simultaneous', 'adj.', 'C1', 243, 'Occurring at exactly the same moment in time.', 'The two explosions were simultaneous, causing confusion among investigators.', 7811),
