  (7808, 'C1|time|yearly', 'yearly', 'yearly', 'adj.', 'C1', 243, 'Happening once per year.', 'The yearly company picnic is scheduled for June.', 7818),
  (7809, 'C1|time|year‑round', 'year‑round', 'year‑round', 'adj.', 'C1', 243, 'Occurring continuously throughout the entire year.', 'The resort offers year‑round activities, from skiing in winter to hiking in summer.', 7816),
