  (7812, 'C1|time|get‑go', 'get‑go', 'get‑go', 'n.', 'C1', 243, 'The point in time when something begins or starts.', 'He was determined to succeed from the get‑go of his career.', 7794),
  (7813, 'C1|time|longstanding', 'longstanding', 'longstanding', 'adj.', 'C1', 243, 'Having existed or persisted for a significant duration.', 'The two countries have a longstanding tradition of cooperation.', 7803),
  (7814, 'C1|time|longtime', 'longtime', 'longtime', 'adj.', 'C1', 243, 'Existing or being in use for a long period.', 'She is a longtime supporter of the local animal shelter.', 7804),
